for path in paths_to_check:
    if os.path.exists(path):
        files = []
        for f in os.listdir(path):
            if f.endswith('.go'):
                files.append(f)
        results[path] = {'exists': True, 'go_files': sorted(files)[:10]}  # First 10 files
    else:
        results[path] = {'exists': False}

