package client

// This file contains unary RPC specific options.

import (
	"fmt"
	"time"

	"github.com/cloudwego/kitex/internal/client"
	"github.com/cloudwego/kitex/pkg/endpoint"
	"github.com/cloudwego/kitex/pkg/utils"
)

// UnaryOption is an option for unary RPC calls.
type UnaryOption = client.UnaryOption

// UnaryOptions holds unary-specific configuration.
type UnaryOptions = client.UnaryOptions

// WithUnaryOptions applies unary-specific options to the client.
func WithUnaryOptions(opts ...UnaryOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryOptions(%d options)", len(opts)))
		for _, opt := range opts {
			opt.F(&o.UnaryOptions, di)
		}
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout for unary calls.
func WithUnaryRPCTimeout(d time.Duration) UnaryOption {
	return UnaryOption{F: func(o *client.UnaryOptions, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRPCTimeout(%dms)", d.Milliseconds()))
		o.RPCTimeout = d
	}}
}

// WithUnaryMiddleware adds middleware for unary RPC calls.
func WithUnaryMiddleware(mw endpoint.UnaryMiddleware) UnaryOption {
	return UnaryOption{F: func(o *client.UnaryOptions, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddleware(%+v)", utils.GetFuncName(mw)))
		o.Middlewares = append(o.Middlewares, mw)
	}}
}
