// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader  Protocol = 1 << iota // 2
	Framed                          // 4
	HTTP                            // 8
	GRPC                            // 16
	HESSIAN2                        // 32
	_reserved1                      // 64 reserved for TTHeaderStreaming
	_reserved2                      // 128 reserved for GRPCStreaming

	TTHeaderStreaming Protocol = 64  // Dedicated streaming flag for TTHeader
	GRPCStreaming     Protocol = 128 // Dedicated streaming flag for gRPC

	TTHeaderFramed = TTHeader | Framed
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Handle zero value
	if tp == 0 {
		return "PurePayload"
	}

	// Check for dedicated single flags first
	switch tp {
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite values by building pipe-separated string
	// in ascending order of bit values
	var parts []string
	flags := []struct {
		val  Protocol
		name string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	for _, flag := range flags {
		if tp&flag.val != 0 {
			parts = append(parts, flag.name)
		}
	}

	if len(parts) > 0 {
		result := parts[0]
		for i := 1; i < len(parts); i++ {
			result += "|" + parts[i]
		}
		return result
	}

	return Unknown
}
