	d := thrift.NewSkipDecoder(in)
	defer d.Release()
	b, err := d.Next(thrift.STRUCT)
	if err != nil {
		return err
	}
	ex := thrift.NewApplicationException(thrift.UNKNOWN_APPLICATION_EXCEPTION, "")
