	defer func() {
		if r := recover(); r != nil {
			klog.Errorf("connPool.Dump panic recovered: %v", r)
		}
	}()

	result := make(map[string]interface{})

	p.conns.Range(func(key, value interface{}) bool {
		addr, ok := key.(string)
		if !ok {
			return true
		}

		trans, ok := value.(*transports)
		if !ok {
			return true
		}

		// Collect transport information for this address
		var transportDumps []interface{}
		for i := uint32(0); i < trans.size; i++ {
			if trans.cliTransports[i] != nil {
				transportInfo := make(map[string]interface{})

				// Safely extract RemoteAddr
				func() {
					defer func() {
						if r := recover(); r != nil {
							klog.Errorf("Failed to get RemoteAddr for transport: %v", r)
						}
					}()
					if remoteAddr := trans.cliTransports[i].RemoteAddr(); remoteAddr != nil {
						transportInfo["remote_addr"] = remoteAddr.String()
					}
